import sys
from datetime import date, timedelta


def minutes(text):
    h, m = map(int, text.split(":"))
    return h * 60 + m


def clock(total):
    hours = total // 60
    mins = total % 60
    return f"{hours:02d}:{mins:02d}"


def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "days":
            settings["days"] = [parts[1], parts[2]]
        elif parts[0] == "hours":
            settings["hours"] = [parts[1], parts[2]]
        elif parts[0] == "duration":
            settings["duration"] = [parts[1]]
        elif parts[0] == "buffer":
            if parts[1]:
                settings["buffer"] = [parts[1]]
            else:
                settings["buffer"] = [0]
        elif parts[0] == "busy":
            who, day_str, start, end = parts
            day = date.fromisoformat(day_str)
            busy[(who, day_str)] = []
            busy[(who, day_str)].append((minutes(start), minutes(end)))

    if "days" not in settings or "hours" not in settings or "duration" not in settings:
        print("Invalid input")
        return

    first = date.fromisoformat(settings["days"][0])
    last = date.fromisoformat(settings["days"][1])
    open_at = minutes(settings["hours"][0])
    close_at = minutes(settings["hours"][1])
    min_duration = int(settings["duration"][0])
    buffer = int(settings.get("buffer", [0])[0])

    day = first
    while day <= last:
        day_str = day.isoformat()
        if day.weekday() >= 5:  # Skip weekends
            day += timedelta(days=1)
            continue

        taken = []
        if ("A", day_str) in busy:
            taken.extend(busy[("A", day_str)])
        if ("B", day_str) in busy:
            taken.extend(busy[("B", day_str)])

        taken.sort()
        slots = []
        cursor = open_at
        for start, end in taken:
            if cursor < start:
                if end - cursor >= min_duration:
                    slots.append(f"{clock(cursor)}-{clock(start)}")
                cursor = end
            else:
                cursor = max(cursor, end)

        if close_at - cursor >= min_duration:
            slots.append(f"{clock(cursor)}-{clock(close_at)}")

        if slots:
            print(f"{day_str} {' '.join(slots)}")
        else:
            print(f"{day_str} none")
        day += timedelta(days=1)


if __name__ == "__main__":
    main()
